	private static final class WeightedBudget implements SamplingBudget {
		final IllegalStateException exhausted = new IllegalStateException("native weighted test work limit");
		int pageLimit = 512;
		int nativeLimit = 256;
		int pages;
		int nativeReads;
		int keys;

		@Override
		public void checkpoint() {
		}

		@Override
		public void nativeRead() {
			if (nativeReads == nativeLimit) {
				throw exhausted;
			}
			nativeReads++;
		}

		@Override
		public void pageAccess() {
			if (pages == pageLimit) {
				throw exhausted;
			}
			pages++;
		}

		@Override
		public void keyAccess() {
			if (keys == 8_192) {
				throw exhausted;
			}
			keys++;
		}
	}

	@Test
	void nativeCountAndPrefixRunsAreExactAcrossBoundaryPages(@TempDir Path directory) throws Exception {
		try (Environment env = new Environment(directory, 0)) {
			env.write(0, 10_000);
			long txn = env.begin(MDB_RDONLY);
			try (var view = env.estimator.readTransaction(txn, 1L)) {
				byte[] lower = key(5);
				byte[] upper = key(17);
				var count = view.countEntriesExact("records", lower, lower.length, true,
						upper, upper.length, false, () -> false);
				assertNotNull(count);
				assertEquals(6_000, count.entries());
				assertEquals(0, count.work().keyPrefixesRead());
				assertTrue(count.work().leafHeadersRead() > 0, "interior leaves contribute exact header counts");
				try (var groups = view.prefixRunsExact("records", lower, lower.length, true,
						upper, upper.length, false, 1, () -> false)) {
					assertNotNull(groups);
					int group = 5;
					PrefixRun run;
					while ((run = groups.next()) != null) {
						assertEquals(group++, Varint.readUnsigned(ByteBuffer.wrap(run.representativeKey())));
						assertEquals(500, run.entries());
					}
					assertEquals(17, group);
					assertTrue(groups.work().keyPrefixesRead() < count.entries(),
							"uniform leaf proofs must skip statement-key interiors");
				}
				byte[] partialLower = key(5, 2750, 0, 0);
				byte[] partialUpper = key(6, 3250, 0, 0);
				try (var groups = view.prefixRunsExact("records", partialLower, partialLower.length, true,
						partialUpper, partialUpper.length, true, 1, () -> false)) {
					assertEquals(250, groups.next().entries());
					assertEquals(251, groups.next().entries());
					assertNull(groups.next());
				}
			} finally {
				mdb_txn_abort(txn);
			}
		}
	}

