	@Test
	void cursorChecksOwnerViewLifetimeAndCancellation(@TempDir Path directory) throws Exception {
		try (Environment env = new Environment(directory, 0)) {
			env.write(0, 10_000);
			long txn = env.begin(MDB_RDONLY);
			try (var view = env.estimator.readTransaction(txn, 1L)) {
				AtomicBoolean cancelled = new AtomicBoolean();
				var cursor = view.prefixRunsExact("records", null, 0, true, null, 0, true, 1, cancelled::get);
				assertNotNull(cursor);
				try (cursor) {
					try (var worker = Executors.newSingleThreadExecutor()) {
						worker.submit(() -> assertThrows(IllegalStateException.class, cursor::next)).get();
					}
					long boundaryPages = cursor.work().leafPagesRead();
					do {
						PrefixRun run = cursor.next();
						assertNotNull(run, "the fixture must contain interior pages beyond both seek boundaries");
						assertEquals(500, run.entries());
					} while (cursor.work().leafPagesRead() == boundaryPages);
					cancelled.set(true);
					assertThrows(CancellationException.class, cursor::next);
					cancelled.set(false);
					view.close();
					assertThrows(IllegalStateException.class, cursor::next);
					cursor.close();
					cursor.close();
				}
			} finally {
				mdb_txn_abort(txn);
			}
		}
	}

